// Input is what the caller sent. It stays reachable for the whole
// process, unlike #Previous, which is only the previous step's result.
var who = string.IsNullOrEmpty(Input.name) ? "world" : Input.name;

// Logger writes into the run log you can open next to the diagram.
Logger.LogInformation($"greeting {who}");

// A step must return a value: the engine compiles this body into a
// method, and a path without return fails the whole model (CS0161).
return new GreetingRequest() { name = who, language = Input.language };
